var t=`0108-sklandrausis`;var i=`world-0108`;var a=`LV`;var r=`northern-europe`;var o=4;var s=88;var u={en:`Sklandrausis`,ua:`Скланраусіс`};var g={en:`A classic dish from Latvia, featuring potato, carrot, sour cream. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Латвія. Основні складники: картопля, морква, сметана. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var l=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 22 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 22 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:22,i:[[`rye-flour`,400,`g`],[`unsalted-butter`,90,`g`],[`water`,180,`ml`],[`table-salt`,4,`g`]]},{en:`Cook the listed ingredients in simmering water for about 18 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 18 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:18,i:[[`potato`,300,`g`],[`carrot`,500,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:5,i:[[`sour-cream`,130,`g`],[`white-granulated-sugar`,90,`g`],[`caraway-seeds`,3,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:15,i:[]},{en:`Bake in a preheated 180°C oven for about 28 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 28 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:28,i:[]}];var d={slug:t,id:i,country:`LV`,region:r,servings:4,minutes:88,title:u,text:g,steps:l};export{a as country,d as default,i as id,s as minutes,r as region,o as servings,t as slug,l as steps,g as text,u as title};